#include <cstring>

struct SRecord20 { unsigned char bytes[20]; };

struct CAllocProxy20 {
    SRecord20* _M_data;
    SRecord20* allocate(unsigned long count, const void* = 0) { return count ? (SRecord20*)std::malloc(count * 20) : 0; }
